using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed the default discriminator property from "Discriminator" to "$type".
            // Preserve "Discriminator" so existing 500K documents remain queryable and
            // direct SQL queries (c.Discriminator) keep working without data migration.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed id generation from "EntityType|Key" to just "Key".
            // Preserve the old format so existing documents (e.g. "Product|123") remain accessible.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // HasIndex removed — EF Core 9 Cosmos provider throws at startup.
        // Manage indexing via the container's indexing policy (Azure Portal / Bicep / Terraform).
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

